import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import { findSubscription } from "./subscription-repository";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

/**
 * The subscription is the authority on an org's plan. The `organizations.plan`
 * column only answers for an org that has no subscription row, so every
 * consumer of `Organization.plan` sees the plan the org is actually on.
 */
async function withSubscriptionPlan(org: Organization): Promise<Organization> {
  const subscription = await findSubscription(org.id);
  return subscription ? { ...org, plan: subscription.plan } : org;
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? withSubscriptionPlan(toOrganization(row)) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? withSubscriptionPlan(toOrganization(row)) : null;
}

